const test=require('node:test'),assert=require('node:assert/strict');const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),temp=fs.mkdtempSync(path.join(os.tmpdir(),'blu-access-ci-')),source=JSON.parse(fs.readFileSync('.github/launcher-src/source.json','utf8'));for(const name of ['access.cjs','theme.cjs'])fs.writeFileSync(path.join(temp,name),source[name]);test.after(()=>fs.rmSync(temp,{recursive:true,force:true}));const {defaults,normalizeAccess,accessDecision,fetchAccess,withPackAccess,resolveAllowed}=require(path.join(temp,'access.cjs'));const {ADMIN_UUID}=require(path.join(temp,'theme.cjs'));const friend={id:'1'.repeat(32),name:'Friend'},stranger={id:'2'.repeat(32),name:'Friend'},owner={id:ADMIN_UUID,name:'renamed-owner'};
test('closed launch allows only verified owner; matching admin display name cannot bypass it',()=>{assert.equal(accessDecision(defaults,friend,Date.now()).allowed,false);assert.equal(accessDecision(defaults,{...friend,name:'ceeseme'},Date.now()).allowed,false);assert.equal(accessDecision(defaults,owner,Date.now()).allowed,true);});
test('invite list uses account UUID and scheduled opening uses trusted server time',()=>{const p={...defaults,allowed:[{uuid:friend.id,name:'Friend'}]};assert.equal(accessDecision({...p,mode:'invited'},friend,0).allowed,true);assert.equal(accessDecision({...p,mode:'invited'},stranger,0).allowed,false);const scheduled={...p,mode:'scheduled',opensAt:'2030-01-01T00:00:00Z'};assert.equal(accessDecision(scheduled,stranger,Date.parse('2029-01-01')).allowed,false);assert.equal(accessDecision(scheduled,stranger,Date.parse(scheduled.opensAt)).allowed,true);assert.equal(accessDecision(scheduled,stranger,NaN).allowed,false);assert.equal(accessDecision(scheduled,friend,0).allowed,true);});
test('denied, unverifiable and invalid-profile players never reach pack download callback',async()=>{let downloads=0;for(const loadPolicy of [async()=>({policy:defaults,serverNow:0}),async()=>{throw Error('offline')},async()=>({policy:{},serverNow:0})])await assert.rejects(withPackAccess({token:'valid',getProfile:async()=>friend,loadPolicy},async()=>{downloads++}));await assert.rejects(withPackAccess({token:'expired',getProfile:async()=>{throw Error('expired')},loadPolicy:async()=>({policy:{...defaults,mode:'open'},serverNow:0})},async()=>{downloads++}));assert.equal(downloads,0);});
test('allowed player reaches downloads only after live identity and remote policy checks',async()=>{const events=[];const result=await withPackAccess({token:'token',getProfile:async t=>{assert.equal(t,'token');events.push('identity');return friend},loadPolicy:async()=>{events.push('policy');return {policy:{...defaults,mode:'open'},serverNow:0}}},async()=>{events.push('download');return 42});assert.equal(result,42);assert.deepEqual(events,['identity','policy','download']);});
test('live owner can test pack while public access is closed, without trusting cached display name',async()=>{assert.equal(await withPackAccess({token:'owner',getProfile:async()=>owner,loadPolicy:()=>{throw Error('not needed')}},async()=>true),true)});
test('lookup resolves official account UUID; remote policy is pinned to repository and uses response Date',async()=>{const allowed=await resolveAllowed('Friend Friend',async url=>{assert.equal(url,'https://api.mojang.com/users/profiles/minecraft/Friend');return {ok:true,json:async()=>friend}});assert.deepEqual(allowed,[{uuid:friend.id,name:'Friend'}]);const result=await fetchAccess('dklslskdkdk-jpg/kazino-pack',async(url,opts)=>{assert.match(url,/^https:\/\/raw\.githubusercontent\.com\/dklslskdkdk-jpg\/kazino-pack\/main\/launcher-access\.json\?t=/);assert.equal(opts.redirect,'error');return {ok:true,text:async()=>JSON.stringify(defaults),headers:{get:()=> 'Wed, 04 Nov 2026 06:20:00 GMT'}}});assert.equal(result.serverNow,Date.parse('2026-11-04T06:20:00Z'));assert.throws(()=>normalizeAccess({...defaults,allowed:[{uuid:'bad'}]}));});
